"""The Undertone page: the phone's Undertone library, edited in the browser (Lumae UT.9).

Everything on the page comes from the Undertone records a phone syncs
(``undertone.py``, contract section 5.8): the light index of the music, the
fields, the details, the presets and their categories. The page never asks the
music server; it writes back through the same revision-checked mutations the
phone uses, so a phone's next sync takes the changes. The file it exports and
imports is the phone's own Undertone file (``lumae-undertone`` version 1).
"""

from html import escape


def render_undertone_page(principal_label, principal_detail):
    html = r"""
<style>
  .ut-page{--ink:#efeae0;--muted:#aaa296;--quiet:#777064;--gold:#d4a54a;--gold-2:#edc774;--bg:#15130f;--panel:#211e18;--control:#332d24;--line:#4b4235;--danger:#ffb4a8;color:var(--ink);color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;padding-bottom:60px}
  .ut-page *{box-sizing:border-box}.ut-page [hidden]{display:none!important}.ut-page button,.ut-page input,.ut-page select,.ut-page textarea{font:inherit}
  .ut-page button{min-height:38px;border-radius:10px;border:1px solid var(--line);background:var(--control);color:var(--ink);padding:7px 13px;font-weight:700;cursor:pointer}.ut-page button:hover{border-color:#776953;background:#40372b}.ut-page button.primary{background:var(--gold);border-color:var(--gold);color:#19150e}.ut-page button.ghost{background:transparent}.ut-page button.danger{color:var(--danger)}.ut-page button:disabled{opacity:.42;cursor:not-allowed}
  .ut-page button:focus-visible,.ut-page input:focus-visible,.ut-page select:focus-visible,.ut-page textarea:focus-visible{outline:3px solid #d4a54a66;outline-offset:2px}
  .ut-page input,.ut-page select,.ut-page textarea{background:#17140f;color:var(--ink);border:1px solid #5d5243;border-radius:10px;padding:9px 11px}
  .ut-app{background:var(--bg);border:1px solid #2e2921;border-radius:18px;overflow:hidden}
  .ut-top{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:22px 24px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,#1b1813,#211b12)}
  .ut-kicker{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);font-weight:800}.ut-top h2{font:500 clamp(1.65rem,3vw,2.35rem) Georgia,serif;letter-spacing:-.025em;margin:3px 0 0}.ut-top p{color:var(--muted);margin:5px 0 0}.ut-scope{font-size:.78rem;color:var(--gold-2)!important}
  .ut-tabs{display:flex;gap:8px;flex-wrap:wrap;padding:12px 24px;border-bottom:1px solid var(--line)}.ut-tabs button{border-radius:999px}.ut-tabs button.active{background:var(--gold);border-color:var(--gold);color:#19150e}
  .ut-body{padding:18px 24px}.ut-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}.ut-toolbar input[type=search]{flex:1;min-width:200px}.ut-count{color:var(--muted);font-size:.82rem;margin-left:auto}
  .ut-table-wrap{overflow:auto;max-height:68vh;border:1px solid #302a22;border-radius:12px}
  .ut-table{border-collapse:separate;border-spacing:0;width:100%;font-size:.86rem;color:var(--ink)}.ut-table th{position:sticky;top:0;z-index:1;background:#211d16;text-align:left;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}
  .ut-table td{padding:8px 10px;border-bottom:1px solid #2c271f;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ut-table tr.selected td{background:#2b2418}.ut-table td.ut-cell{cursor:pointer;color:var(--ink)}.ut-table td.ut-cell:hover{background:#30291f}.ut-table td.ut-cell.empty{color:var(--quiet)}.ut-table input[type=checkbox]{accent-color:var(--gold);width:17px;height:17px}
  .ut-sub{color:var(--muted)}.ut-empty{color:var(--muted);padding:40px 10px;text-align:center}.ut-more{display:block;margin:14px auto}
  .ut-section{margin-bottom:22px}.ut-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:8px;border-bottom:1px solid var(--line);margin-bottom:6px}.ut-section-head h3{font:1.3rem Georgia,serif;margin:0;display:flex;align-items:center;gap:10px}
  .ut-hue{width:12px;height:12px;border-radius:50%;display:inline-block}.ut-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:9px 4px;border-bottom:1px solid #2c271f}.ut-row strong{display:block}.ut-row .ut-sub{font-size:.8rem;margin-top:3px}.ut-actions{display:flex;gap:6px;flex-wrap:wrap}
  .ut-card{padding:16px;border:1px solid var(--line);border-radius:13px;background:#191611;margin-bottom:14px}.ut-card h4{font:1.12rem Georgia,serif;margin:0 0 6px}.ut-card p{color:var(--muted);line-height:1.5;margin:0 0 12px}
  .ut-page dialog{width:min(620px,calc(100vw - 24px));border:1px solid var(--line);border-radius:18px;background:var(--panel);color:var(--ink);padding:0;box-shadow:0 28px 100px #000d}.ut-page dialog::backdrop{background:rgba(0,0,0,.76)}
  .ut-dialog-head,.ut-dialog-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 18px;border-bottom:1px solid var(--line)}.ut-dialog-foot{border:0;border-top:1px solid var(--line)}.ut-dialog-head h3{font:1.25rem Georgia,serif;margin:0}.ut-dialog-body{padding:16px 18px;display:grid;gap:12px}.ut-dialog-body label{display:grid;gap:6px}.ut-hint{color:var(--muted);font-size:.8rem}
  .ut-status{min-height:20px;color:var(--gold-2);font-size:.85rem}.ut-status.error{color:var(--danger)}
  .ut-toast{position:fixed;z-index:100;left:50%;bottom:24px;transform:translateX(-50%);width:min(480px,calc(100vw - 28px));background:#30291f;border:1px solid #675944;border-radius:12px;padding:12px 14px;box-shadow:0 16px 45px #000a}
  @media(max-width:760px){.ut-top,.ut-body,.ut-tabs{padding-left:14px;padding-right:14px}.ut-table td{max-width:160px}}
</style>
<div class="ut-page">
  <section class="ut-app" id="ut-app">
    <header class="ut-top">
      <div><span class="ut-kicker">Undertone · __PRINCIPAL__</span><h2 id="ut-title">Undertone</h2><p id="ut-summary">Your focus and sleep music, as your phone syncs it.</p><p class="ut-scope">__PRINCIPAL_DETAIL__</p></div>
      <label id="ut-source-wrap" hidden><span class="ut-hint">Library</span><select id="ut-source" aria-label="Undertone library"></select></label>
    </header>
    <nav class="ut-tabs" id="ut-tabs" aria-label="Undertone sections"><button type="button" data-view="music" class="active">Music</button><button type="button" data-view="presets">Presets</button><button type="button" data-view="fields">Fields</button><button type="button" data-view="file">File</button></nav>
    <div class="ut-body" id="ut-body"><p class="ut-empty">Loading Undertone…</p></div>
  </section>

  <dialog id="ut-dialog" aria-labelledby="ut-dialog-title">
    <form id="ut-dialog-form" method="dialog">
      <header class="ut-dialog-head"><h3 id="ut-dialog-title" tabindex="-1"></h3><button type="button" data-close aria-label="Close">×</button></header>
      <div class="ut-dialog-body" id="ut-dialog-body"></div>
      <footer class="ut-dialog-foot"><span class="ut-status" id="ut-dialog-status" role="status"></span><div class="ut-actions" id="ut-dialog-actions"></div></footer>
    </form>
  </dialog>
  <div class="ut-toast" id="ut-toast" role="status" hidden></div>
</div>
<script>
(()=>{
'use strict';
const api='api/undertone';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const HUES={sky:'#7fb4e6',lavender:'#b39ddb',teal:'#5fb8a8',rose:'#e39aa8',gold:'#d4a54a'};
const KINDS={tags:'Tags',oneOf:'One of',number:'Number',boolean:'Yes or no',text:'Text'};
const records=new Map();
let sources=[],source=null,maxBatch=200,view='music',kind='track',query='',shown=300,selected=new Set(),visibleRows=[],toastTimer=null;

async function req(url,opts={}){const headers=opts.headers||{},rest={...opts};delete rest.headers;const r=await fetch(url,{...rest,headers:{'Content-Type':'application/json',...headers}});let body;try{body=await r.json()}catch(_){body={error:`Request failed (${r.status})`}}if(!r.ok)throw Object.assign(new Error(body.error||'Request failed'),{status:r.status,body});return body}
function toast(text){const el=$('ut-toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true},5000)}
function plural(n,one,many){return `${n} ${n===1?one:many}`}

// ---------------------------------------------------------------- records
function bodyOf(id){return records.get(id)?.record?.body||null}
function live(prefix){const out=[];for(const [id,r] of records)if(id.startsWith(prefix)&&r.record)out.push({id,...r.record.body});return out}
function fields(){return live('field:').sort((a,b)=>(a.position??0)-(b.position??0)||String(a.name).localeCompare(b.name))}
function fieldsFor(k){return fields().filter(f=>!f.hidden&&(Array.isArray(f.on)?f.on:['track','album']).includes(k))}
function items(k){return live(k==='track'?'item:t:':'item:a:')}
function detailId(k,owner,field){return `detail:${k}:${owner}:${field}`}
function valueOf(k,owner,field){return bodyOf(detailId(k,owner,field))?.value}
function categories(){return live('category:').sort((a,b)=>(a.position??0)-(b.position??0))}
function presets(){return live('preset:').sort((a,b)=>(a.position??0)-(b.position??0))}
function groups(){return live('group:')}
function sourceInfo(){return bodyOf('item:source')||{}}

async function loadSource(){records.clear();selected.clear();let cursor=0;for(let page=0;page<200;page+=1){const data=await req(`${api}/changes?source=${encodeURIComponent(source)}&cursor=${cursor}&limit=1000`);for(const r of data.records)records.set(r.id,r);cursor=data.cursor;if(!data.hasMore)break}}

/** Writes in batches over the revisions this page holds; a record changed elsewhere meanwhile is written once more over its new revision (the page's edit is the newer one). */
async function save(writes){const pending=writes.filter(w=>w.body!==null||records.get(w.id)?.record).map(w=>({...w,tries:0}));let failed=0,done=0;while(pending.length){const chunk=pending.splice(0,maxBatch),now=Date.now(),tag=Math.random().toString(36).slice(2,10);const mutations=chunk.map((w,i)=>{const base=records.get(w.id)?.revision||0,id=`web.${now}.${tag}.${i}`;return w.body===null?{id,operation:'delete',recordId:w.id,baseRevision:base,at:now}:{id,operation:'put',recordId:w.id,baseRevision:base,record:{kind:w.kind,body:{...w.body,updatedAt:now}}}});const data=await req(`${api}/mutations/batch?source=${encodeURIComponent(source)}`,{method:'POST',body:JSON.stringify({mutations})});data.results.forEach((r,i)=>{const w=chunk[i];if(r.status===200&&r.record){records.set(r.record.id,r.record);done+=1}else if(r.status===409&&r.error==='undertone_conflict'){if(r.record)records.set(r.record.id,r.record);else records.delete(w.id);if(w.tries<1){w.tries+=1;pending.push(w)}else failed+=1}else failed+=1})}return {done,failed}}

// ---------------------------------------------------------------- values
function fmt(v){if(v==null)return '';if(Array.isArray(v))return v.join(', ');if(typeof v==='object')return `${v.min}–${v.max}`;if(typeof v==='boolean')return v?'Yes':'No';return String(v)}
function parseNumber(text){const t=String(text).trim().replace(',', '.');const m=t.match(/^(-?\d+(?:\.\d+)?)\s*(?:-|–|to)\s*(-?\d+(?:\.\d+)?)$/i);if(m){const a=Number(m[1]),b=Number(m[2]);const lo=Math.min(a,b),hi=Math.max(a,b);return lo===hi?lo:{min:lo,max:hi}}if(t==='')return null;const n=Number(t);return Number.isFinite(n)?n:null}
function normalize(k,v){if(k==='tags'){const list=Array.isArray(v)?v:typeof v==='string'?v.split(/[|,]/):[];const out=[...new Set(list.filter(x=>typeof x==='string').map(x=>x.trim()).filter(Boolean))];return out.length?out:null}if(k==='oneOf'||k==='text')return typeof v==='string'&&v.trim()?v.trim():null;if(k==='number'){if(typeof v==='number')return Number.isFinite(v)?v:null;if(v&&typeof v==='object'&&Number.isFinite(v.min)&&Number.isFinite(v.max)){const lo=Math.min(v.min,v.max),hi=Math.max(v.min,v.max);return lo===hi?lo:{min:lo,max:hi}}if(typeof v==='string')return parseNumber(v);return null}if(k==='boolean'){if(typeof v==='boolean')return v;if(typeof v==='string'){const t=v.trim().toLowerCase();if(['yes','true','1','y'].includes(t))return true;if(['no','false','0','n'].includes(t))return false}return null}return null}
function detailWrite(k,owner,field,value){const id=detailId(k,owner,field.id);if(value==null)return {id,kind:'detail',body:null};return {id,kind:'detail',body:{ownerKind:k,ownerId:owner,fieldId:field.id,value,origin:'user'}}}

// ---------------------------------------------------------------- music
function rowsFor(){const list=items(kind),fs=fieldsFor(kind),q=query.toLowerCase();const rows=list.filter(it=>{if(!q)return true;const text=[it.title,it.artist,it.album,...fs.map(f=>fmt(valueOf(kind,it.id,f.id)))].join(' ').toLowerCase();return text.includes(q)});rows.sort((a,b)=>kind==='track'?String(a.artist).localeCompare(b.artist)||String(a.album).localeCompare(b.album)||(a.discNumber||0)-(b.discNumber||0)||(a.trackNumber||0)-(b.trackNumber||0)||String(a.title).localeCompare(b.title):String(a.artist).localeCompare(b.artist)||String(a.title).localeCompare(b.title));return rows}
function renderMusic(){const fs=fieldsFor(kind);visibleRows=rowsFor();const rows=visibleRows.slice(0,shown);const all=rows.length>0&&rows.every(r=>selected.has(r.id));const head=`<tr><th><input type="checkbox" id="ut-all" aria-label="Select every row shown" ${all?'checked':''}></th><th>Title</th><th>Artist</th>${kind==='track'?'<th>Album</th>':''}${fs.map(f=>`<th>${esc(f.name)}</th>`).join('')}</tr>`;const body=rows.map((it,i)=>`<tr class="${selected.has(it.id)?'selected':''}"><td><input type="checkbox" data-row="${i}" aria-label="Select ${esc(it.title)}" ${selected.has(it.id)?'checked':''}></td><td title="${esc(it.title)}">${esc(it.title)}</td><td class="ut-sub">${esc(it.artist)}</td>${kind==='track'?`<td class="ut-sub">${esc(it.album)}</td>`:''}${fs.map(f=>{const v=fmt(valueOf(kind,it.id,f.id));return `<td class="ut-cell ${v?'':'empty'}" data-row="${i}" data-field="${esc(f.id)}" tabindex="0">${v?esc(v):'—'}</td>`}).join('')}</tr>`).join('');$('ut-body').innerHTML=`<div class="ut-toolbar"><input type="search" id="ut-search" placeholder="Search titles, artists, albums and details" value="${esc(query)}" aria-label="Search"><select id="ut-kind" aria-label="Show"><option value="track" ${kind==='track'?'selected':''}>Tracks</option><option value="album" ${kind==='album'?'selected':''}>Albums</option></select><button type="button" class="primary" id="ut-set" ${selected.size?'':'disabled'}>Set a field…</button><button type="button" id="ut-paste">Paste a column…</button><span class="ut-count">${plural(visibleRows.length,kind,kind+'s')}${selected.size?` · ${selected.size} selected`:''}</span></div>${visibleRows.length?`<div class="ut-table-wrap"><table class="ut-table"><thead>${head}</thead><tbody>${body}</tbody></table></div>${visibleRows.length>shown?'<button type="button" class="ut-more" id="ut-more">Show more</button>':''}`:`<p class="ut-empty">${items(kind).length?'Nothing matches.':'No music here yet. With a version of Lumae that has Undertone, turn on Sync with Lumae Analysis in Settings → Undertone.'}</p>`}`;
  $('ut-search').oninput=e=>{query=e.target.value;shown=300;renderMusicSoon()};$('ut-kind').onchange=e=>{kind=e.target.value;selected.clear();shown=300;renderMusic()};$('ut-set').onclick=()=>openSet([...selected],null);$('ut-paste').onclick=openPaste;if($('ut-more'))$('ut-more').onclick=()=>{shown+=300;renderMusic()};
  const allBox=$('ut-all');if(allBox)allBox.onchange=e=>{for(const r of rows)e.target.checked?selected.add(r.id):selected.delete(r.id);renderMusic()};
  document.querySelectorAll('#ut-body input[data-row]').forEach(box=>box.onchange=e=>{const it=rows[Number(box.dataset.row)];e.target.checked?selected.add(it.id):selected.delete(it.id);renderMusic()});
  document.querySelectorAll('#ut-body td.ut-cell').forEach(cell=>{const open=()=>openSet([rows[Number(cell.dataset.row)].id],cell.dataset.field);cell.onclick=open;cell.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}})}
let searchTimer=null;function renderMusicSoon(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{renderMusic();const s=$('ut-search');s.focus();s.setSelectionRange(s.value.length,s.value.length)},250)}

function valueControl(field,current){const v=current;if(field.kind==='oneOf')return `<select id="ut-value"><option value="">(none)</option>${(field.values||[]).map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`;if(field.kind==='boolean')return `<select id="ut-value"><option value="">(none)</option><option value="yes" ${v===true?'selected':''}>Yes</option><option value="no" ${v===false?'selected':''}>No</option></select>`;const hint=field.kind==='tags'?'Tags, with commas between':field.kind==='number'?(kind==='album'?'A number, or a range like 55–65':'A number'):'Text';return `<input id="ut-value" value="${esc(fmt(v))}" placeholder="${hint}" autocomplete="off"${field.kind==='tags'?` list="ut-suggest"`:''}><datalist id="ut-suggest">${(field.values||[]).map(o=>`<option value="${esc(o)}">`).join('')}</datalist>`}
function openSet(ids,fieldId){const fs=fieldsFor(kind);if(!fs.length){toast('No fields for these yet.');return}let field=fs.find(f=>f.id===fieldId)||fs[0];const current=()=>ids.length===1?valueOf(kind,ids[0],field.id):undefined;const draw=()=>{$('ut-dialog-body').innerHTML=`<label>Field<select id="ut-field">${fs.map(f=>`<option value="${esc(f.id)}" ${f.id===field.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label>Value${valueControl(field,current())}</label><p class="ut-hint">Applies to ${plural(ids.length,kind,kind+'s')}. Your phone takes it at its next sync.</p>`;$('ut-field').onchange=e=>{field=fs.find(f=>f.id===e.target.value);draw()}};
  dialog(ids.length===1?'Set a field':`Set a field on ${ids.length}`,draw,[['Clear value','ghost',async()=>apply(null)],['Save','primary',async()=>{const raw=$('ut-value').value;const value=normalize(field.kind,raw);if(raw.trim()&&value==null){status('That value doesn’t fit this field.',true);return false}return apply(value)}]]);
  async function apply(value){const result=await save(ids.map(id=>detailWrite(kind,id,field,value)));finish(result,`${field.name} ${value==null?'cleared':'set'} on ${plural(result.done,kind,kind+'s')}.`);renderMusic()}}
function openPaste(){const fs=fieldsFor(kind);if(!fs.length){toast('No fields for these yet.');return}const start=Math.max(0,visibleRows.findIndex(r=>selected.has(r.id)));dialog('Paste a column',()=>{$('ut-dialog-body').innerHTML=`<label>Field<select id="ut-field">${fs.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label><label>Values, one per line<textarea id="ut-lines" rows="10" placeholder="60&#10;62&#10;58"></textarea></label><p class="ut-hint">Line 1 goes to ${esc(visibleRows[start]?.title||'the first row')} and on down the rows shown. An empty line leaves its row as it is.</p>`},[['Paste','primary',async()=>{const field=fs.find(f=>f.id===$('ut-field').value);const lines=$('ut-lines').value.split(/\r?\n/);if(lines.length&&lines[lines.length-1]==='')lines.pop();const writes=[];let bad=0;lines.forEach((line,i)=>{const row=visibleRows[start+i];if(!row||!line.trim())return;const value=normalize(field.kind,line);if(value==null){bad+=1;return}writes.push(detailWrite(kind,row.id,field,value))});if(!writes.length){status(bad?'None of these values fit this field.':'Nothing to paste.',true);return false}const result=await save(writes);finish(result,`${field.name} set on ${plural(result.done,kind,kind+'s')}${bad?`; ${plural(bad,'value didn’t','values didn’t')} fit and ${bad===1?'was':'were'} left out`:''}.`);renderMusic()}]])}

// ---------------------------------------------------------------- presets
function playsLabel(p){const plays=p.plays||{};if(plays.kind==='track')return bodyOf(`item:t:${plays.trackId}`)?.title||'A track';if(plays.kind==='album')return bodyOf(`item:a:${plays.albumId}`)?.title||'An album';if(plays.kind==='group')return bodyOf(`group:${plays.groupId}`)?.name||'A group';return 'Music from a filter'}
function timerLabel(p){const t=p.timer;if(!t)return 'No timer';if(t.kind==='minutes')return `${t.minutes} min`;return `Until ${t.time}`}
function renderPresets(){const cats=categories(),ps=presets();$('ut-body').innerHTML=`<div class="ut-toolbar"><button type="button" class="primary" id="ut-new-category">New category</button><span class="ut-count">${plural(ps.length,'preset','presets')}. Make presets on your phone; edit them here.</span></div>${cats.map(c=>`<section class="ut-section"><div class="ut-section-head"><h3><span class="ut-hue" style="background:${HUES[c.hue]||HUES.sky}"></span>${esc(c.name)}</h3><div class="ut-actions"><button type="button" data-edit-category="${esc(c.id)}">Edit</button><button type="button" class="danger" data-delete-category="${esc(c.id)}">Delete</button></div></div>${ps.filter(p=>p.categoryId===c.id).map(p=>`<div class="ut-row"><div><strong>${esc(p.name)}</strong><div class="ut-sub">${esc(playsLabel(p))} · ${p.between==='fade'?'Fade between':'Gapless'} · ${esc(timerLabel(p))} · ${Math.round((p.volume??1)*100)}%</div></div><div class="ut-actions"><button type="button" data-edit-preset="${esc(p.id)}">Edit</button><button type="button" class="danger" data-delete-preset="${esc(p.id)}">Delete</button></div></div>`).join('')||'<p class="ut-sub">No presets yet.</p>'}</section>`).join('')||'<p class="ut-empty">No categories yet.</p>'}`;
  $('ut-new-category').onclick=()=>editCategory(null);document.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>editCategory(b.dataset.editCategory));document.querySelectorAll('[data-delete-category]').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.deleteCategory));document.querySelectorAll('[data-edit-preset]').forEach(b=>b.onclick=()=>editPreset(b.dataset.editPreset));document.querySelectorAll('[data-delete-preset]').forEach(b=>b.onclick=()=>deletePreset(b.dataset.deletePreset))}
function editCategory(id){const c=id?bodyOf(`category:${id}`):null;dialog(c?'Edit category':'New category',()=>{$('ut-dialog-body').innerHTML=`<label>Name<input id="ut-name" maxlength="40" value="${esc(c?.name||'')}"></label><label>Colour<select id="ut-hue">${Object.keys(HUES).map(h=>`<option value="${h}" ${h===(c?.hue||'sky')?'selected':''}>${h[0].toUpperCase()+h.slice(1)}</option>`).join('')}</select></label>`},[['Save','primary',async()=>{const name=$('ut-name').value.trim();if(!name){status('Give the category a name.',true);return false}const cid=id||`c_web_${Math.random().toString(36).slice(2,10)}`;const position=c?c.position:Math.max(-1,...categories().map(x=>x.position??0))+1;const result=await save([{id:`category:${cid}`,kind:'category',body:{id:cid,name:name.slice(0,40),hue:$('ut-hue').value,position}}]);finish(result,`${name} saved.`);renderPresets()}]])}
function deleteCategory(id){const c=bodyOf(`category:${id}`),inside=presets().filter(p=>p.categoryId===id);dialog('Delete category?',()=>{$('ut-dialog-body').innerHTML=`<p>${esc(c?.name)} and ${plural(inside.length,'preset','presets')} in it are deleted on your phones at their next sync. The music stays.</p>`},[['Delete','danger',async()=>{const result=await save([...inside.map(p=>({id:`preset:${p.id}`,kind:'preset',body:null})),{id:`category:${id}`,kind:'category',body:null}]);finish(result,`${c?.name} deleted.`);renderPresets()}]])}
function editPreset(id){const p=bodyOf(`preset:${id}`);if(!p)return;const t=p.timer;dialog('Edit preset',()=>{$('ut-dialog-body').innerHTML=`<label>Name<input id="ut-name" maxlength="60" value="${esc(p.name)}"></label><label>Category<select id="ut-category">${categories().map(c=>`<option value="${esc(c.id)}" ${c.id===p.categoryId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Between tracks<select id="ut-between"><option value="gapless" ${p.between!=='fade'?'selected':''}>Gapless</option><option value="fade" ${p.between==='fade'?'selected':''}>Fade between</option></select></label><label>Timer, in minutes<input id="ut-minutes" type="number" min="1" max="1440" value="${t?.kind==='minutes'?t.minutes:''}" placeholder="${t?.kind==='until'?`Until ${esc(t.time)} (set on your phone)`:'No timer'}"></label><label>Volume, in percent<input id="ut-volume" type="number" min="5" max="100" value="${Math.round((p.volume??1)*100)}"></label><label>Fade in, in seconds<input id="ut-fadein" type="number" min="0" max="60" value="${p.fadeInSeconds??0}"></label>`},[['Save','primary',async()=>{const name=$('ut-name').value.trim();if(!name){status('Give the preset a name.',true);return false}const minutes=$('ut-minutes').value.trim();const timer=minutes?{kind:'minutes',minutes:Math.max(1,Math.min(1440,Math.round(Number(minutes))||1))}:(t?.kind==='until'?t:null);const {id:_id,updatedAt:_u,...rest}=p;const body={...rest,id,name:name.slice(0,60),categoryId:$('ut-category').value,between:$('ut-between').value,timer,volume:Math.max(.05,Math.min(1,(Number($('ut-volume').value)||100)/100)),fadeInSeconds:Math.max(0,Math.min(60,Number($('ut-fadein').value)||0))};const result=await save([{id:`preset:${id}`,kind:'preset',body}]);finish(result,`${name} saved.`);renderPresets()}]])}
function deletePreset(id){const p=bodyOf(`preset:${id}`);dialog('Delete preset?',()=>{$('ut-dialog-body').innerHTML=`<p>${esc(p?.name)} is deleted on your phones at their next sync. The music stays.</p>`},[['Delete','danger',async()=>{const result=await save([{id:`preset:${id}`,kind:'preset',body:null}]);finish(result,`${p?.name} deleted.`);renderPresets()}]])}

// ---------------------------------------------------------------- fields
function onLabel(on){const list=Array.isArray(on)?on:['track','album'];return list.length===2?'Tracks and albums':list[0]==='track'?'Tracks':'Albums'}
function renderFields(){const fs=fields();$('ut-body').innerHTML=`<div class="ut-toolbar"><button type="button" class="primary" id="ut-new-field">New field</button><span class="ut-count">Hidden fields keep their values.</span></div>${fs.map(f=>`<div class="ut-row"><div><strong>${esc(f.name)}${f.hidden?' <span class="ut-sub">(hidden)</span>':''}</strong><div class="ut-sub">${KINDS[f.kind]||esc(f.kind)} · ${onLabel(f.on)}${(f.values||[]).length?` · ${esc(f.values.join(', '))}`:''}</div></div><div class="ut-actions"><button type="button" data-rename="${esc(f.id)}">Rename</button><button type="button" data-hide="${esc(f.id)}">${f.hidden?'Show':'Hide'}</button>${f.builtIn?'':`<button type="button" class="danger" data-delete-field="${esc(f.id)}">Delete</button>`}</div></div>`).join('')||'<p class="ut-empty">No fields yet. Your phone sends them at its next sync.</p>'}`;
  $('ut-new-field').onclick=newField;document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>renameField(b.dataset.rename));document.querySelectorAll('[data-hide]').forEach(b=>b.onclick=async()=>{const f=bodyOf(`field:${b.dataset.hide}`);const result=await save([{id:`field:${f.id}`,kind:'field',body:{...f,hidden:!f.hidden}}]);finish(result,`${f.name} ${f.hidden?'shown':'hidden'}.`);renderFields()});document.querySelectorAll('[data-delete-field]').forEach(b=>b.onclick=()=>deleteField(b.dataset.deleteField))}
function slug(name){const taken=new Set(fields().map(f=>f.id));const base=name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,24)||'field';let id=base,n=2;while(taken.has(id))id=`${base}_${n++}`;return id}
function newField(){dialog('New field',()=>{$('ut-dialog-body').innerHTML=`<label>Name<input id="ut-name" maxlength="40" placeholder="Like Room or Mood"></label><label>Kind<select id="ut-fkind">${Object.entries(KINDS).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>On<select id="ut-on"><option value="both">Tracks and albums</option><option value="track">Tracks</option><option value="album">Albums</option></select></label><label>Choices or suggestions, with commas between<input id="ut-values" placeholder="For One of: the choices. For Tags: suggestions."></label>`},[['Add field','primary',async()=>{const name=$('ut-name').value.trim(),fk=$('ut-fkind').value,on=$('ut-on').value;const values=[...new Set($('ut-values').value.split(',').map(v=>v.trim()).filter(Boolean))];if(!name){status('Give the field a name.',true);return false}if(fk==='oneOf'&&values.length<2){status('One of needs at least two choices.',true);return false}const id=slug(name);const result=await save([{id:`field:${id}`,kind:'field',body:{id,name:name.slice(0,40),kind:fk,on:on==='both'?['track','album']:[on],values:fk==='oneOf'||fk==='tags'?values:[],hidden:false,position:Math.max(-1,...fields().map(f=>f.position??0))+1,builtIn:false}}]);finish(result,`${name} added.`);renderFields()}]])}
function renameField(id){const f=bodyOf(`field:${id}`);dialog('Rename field',()=>{$('ut-dialog-body').innerHTML=`<label>Name<input id="ut-name" maxlength="40" value="${esc(f.name)}"></label>`},[['Save','primary',async()=>{const name=$('ut-name').value.trim();if(!name){status('Give the field a name.',true);return false}const result=await save([{id:`field:${id}`,kind:'field',body:{...f,name:name.slice(0,40)}}]);finish(result,`Renamed to ${name}.`);renderFields()}]])}
function deleteField(id){const f=bodyOf(`field:${id}`);const values=live('detail:').filter(d=>d.fieldId===id);dialog('Delete field?',()=>{$('ut-dialog-body').innerHTML=`<p>${esc(f.name)} and its ${plural(values.length,'value','values')} are deleted on your phones at their next sync.</p>`},[['Delete','danger',async()=>{const result=await save([...values.map(d=>({id:detailId(d.ownerKind,d.ownerId,id),kind:'detail',body:null})),{id:`field:${id}`,kind:'field',body:null}]);finish(result,`${f.name} deleted.`);renderFields()}]])}

// ---------------------------------------------------------------- the Undertone file
function buildFile(){const info=sourceInfo(),details=new Map();for(const d of live('detail:')){const ref=`${d.ownerKind==='album'?'a':'t'}:${d.ownerId}`;const own=details.get(ref)||{};own[d.fieldId]=d.value;details.set(ref,own)}const needed=new Set(details.keys());for(const g of groups())for(const a of g.albumIds||[])needed.add(`a:${a}`);for(const p of presets()){if(p.plays?.kind==='track')needed.add(`t:${p.plays.trackId}`);if(p.plays?.kind==='album')needed.add(`a:${p.plays.albumId}`)}const out=[];for(const ref of [...needed].sort()){const id=ref.slice(2);if(ref[0]==='t'){const t=bodyOf(`item:t:${id}`);out.push({ref,kind:'track',match:t?{id,path:t.path??null,musicBrainzId:t.musicBrainzId??null,artist:t.artist,album:t.album,title:t.title,track:t.trackNumber??null,seconds:t.seconds??null}:{id},details:details.get(ref)||{}})}else{const a=bodyOf(`item:a:${id}`);out.push({ref,kind:'album',match:a?{id,artist:a.artist,album:a.title}:{id},details:details.get(ref)||{}})}}
  const strip=({updatedAt,...rest})=>rest;return {format:'lumae-undertone',version:1,exportedAt:new Date().toISOString(),source:{server:info.serverType||'',library:info.libraryName||'',fingerprint:source},fields:fields().map(strip),categories:categories().map(strip),groups:groups().map(g=>({id:g.id,name:g.name,position:g.position,albums:(g.albumIds||[]).map(a=>`a:${a}`)})),presets:presets().map(p=>{const {categoryId,plays,...rest}=strip(p);return {...rest,category:categoryId,plays:plays?.kind==='track'?{kind:'track',ref:`t:${plays.trackId}`}:plays?.kind==='album'?{kind:'album',ref:`a:${plays.albumId}`}:plays?.kind==='group'?{kind:'group',ref:plays.groupId}:plays}}),items:out}}
function exportFile(){const file=buildFile(),d=new Date(),name=`undertone-${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}.json`;const url=URL.createObjectURL(new Blob([JSON.stringify(file,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Saved ${name}: ${plural(file.items.length,'item','items')} with details.`)}
const norm=s=>String(s??'').trim().toLowerCase();
/** The phone's matching ladder: the same library's ids, then MusicBrainz id, path, and artist, album, title and track number with the length within 2 s. A tie is left out. */
function matchItems(file){const same=file.source?.fingerprint===source,tracks=items('track'),albums=items('album');const by=(list,key)=>{const m=new Map();for(const x of list){const k=key(x);if(!k)continue;const l=m.get(k)||[];l.push(x);m.set(k,l)}return m};const mb=by(tracks,t=>t.musicBrainzId&&norm(t.musicBrainzId)),path=by(tracks,t=>t.path&&norm(t.path)),tag=by(tracks,t=>[norm(t.artist),norm(t.album),norm(t.title),t.trackNumber??''].join('|')),alb=by(albums,a=>[norm(a.artist),norm(a.title)].join('|'));const resolved=new Map();let ties=0,missing=0;for(const it of file.items||[]){const m=it.match||{},isTrack=it.kind==='track';if(same&&records.get(`item:${isTrack?'t':'a'}:${m.id}`)?.record){resolved.set(it.ref,m.id);continue}let found=null;if(isTrack){for(const [map,key,check] of [[mb,m.musicBrainzId&&norm(m.musicBrainzId)],[path,m.path&&norm(m.path)],[tag,[norm(m.artist),norm(m.album),norm(m.title),m.track??''].join('|'),true]]){if(!key)continue;let c=map.get(key)||[];if(check&&typeof m.seconds==='number')c=c.filter(t=>typeof t.seconds!=='number'||Math.abs(t.seconds-m.seconds)<=2);if(c.length===1){found=c[0].id;break}if(c.length>1){found=false;break}}}else{const c=alb.get([norm(m.artist),norm(m.album)].join('|'))||[];found=c.length===1?c[0].id:c.length>1?false:null}if(found){resolved.set(it.ref,found)}else if(found===false)ties+=1;else missing+=1}return {resolved,ties,missing}}
let importing=null;
function renderFile(){$('ut-body').innerHTML=`<section class="ut-card"><h4>Export the Undertone file</h4><p>Presets, categories, groups, fields and details, with what Lumae needs to find the music again. Never the music or sign-ins. Your phone imports it in Settings → Undertone → Import.</p><button type="button" class="primary" id="ut-export">Export</button></section><section class="ut-card"><h4>Import an Undertone file</h4><p>From a phone or this page. Music is found again by its ids in the same library, else by MusicBrainz id, path, or artist, album, title and track.</p><input type="file" id="ut-import-file" accept="application/json,.json" aria-label="Choose an Undertone file"><div id="ut-import-plan"></div></section>`;$('ut-export').onclick=exportFile;$('ut-import-file').onchange=readImport}
async function readImport(event){const plan=$('ut-import-plan');importing=null;const file=event.target.files?.[0];if(!file)return;let data;try{data=JSON.parse(await file.text())}catch(_){plan.innerHTML='<p class="ut-status error">This isn’t an Undertone file. Nothing was imported.</p>';return}if(data?.format!=='lumae-undertone'||!(data.version>=1)){plan.innerHTML='<p class="ut-status error">This isn’t an Undertone file. Nothing was imported.</p>';return}if(data.version>1){plan.innerHTML='<p class="ut-status error">This file comes from a newer Lumae. Nothing was imported.</p>';return}const match=matchItems(data);importing={data,match};plan.innerHTML=`<p>${plural((data.items||[]).length,'item','items')}: ${match.resolved.size} found${match.ties?`, ${match.ties} with more than one match (left out)`:''}${match.missing?`, ${match.missing} not in this library`:''}. ${plural((data.presets||[]).length,'preset','presets')}, ${plural((data.fields||[]).length,'field','fields')}.</p><label>When both have a value<select id="ut-import-mode"><option value="keepMine">Keep what’s here</option><option value="fileWins">The file’s wins</option></select></label><p><button type="button" class="primary" id="ut-import-go">Import</button></p><p class="ut-status" id="ut-import-status" role="status"></p>`;$('ut-import-go').onclick=applyImport}
async function applyImport(){if(!importing)return;const {data,match}=importing,keep=$('ut-import-mode').value==='keepMine',button=$('ut-import-go');button.disabled=true;const writes=[],fieldKinds=new Map(fields().map(f=>[f.id,f.kind]));for(const f of data.fields||[]){if(!f?.id||!f.name||!KINDS[f.kind])continue;const mine=bodyOf(`field:${f.id}`);if(!mine||!keep)writes.push({id:`field:${f.id}`,kind:'field',body:{id:f.id,name:String(f.name).slice(0,60),kind:f.kind,on:Array.isArray(f.on)&&f.on.length?f.on:['track','album'],values:Array.isArray(f.values)?f.values:[],hidden:!!f.hidden,position:Number.isFinite(f.position)?f.position:0,builtIn:!!(mine?.builtIn||f.builtIn)}});if(!mine||!keep)fieldKinds.set(f.id,f.kind);else fieldKinds.set(f.id,mine.kind)}const cats=new Set(categories().map(c=>c.id));for(const c of data.categories||[]){if(!c?.id||!c.name)continue;cats.add(c.id);if(!bodyOf(`category:${c.id}`)||!keep)writes.push({id:`category:${c.id}`,kind:'category',body:{id:c.id,name:String(c.name).slice(0,40),hue:HUES[c.hue]?c.hue:'sky',position:Number.isFinite(c.position)?c.position:0}})}const groupIds=new Set(groups().map(g=>g.id));for(const g of data.groups||[]){const albumIds=(g.albums||[]).map(r=>match.resolved.get(r)).filter(Boolean);if(!g?.id||!g.name||!albumIds.length)continue;groupIds.add(g.id);if(!bodyOf(`group:${g.id}`)||!keep)writes.push({id:`group:${g.id}`,kind:'group',body:{id:g.id,name:String(g.name).slice(0,60),position:Number.isFinite(g.position)?g.position:0,albumIds:[...new Set(albumIds)]}})}let skipped=0;for(const p of data.presets||[]){if(!p?.id||!p.name||!cats.has(p.category)){skipped+=1;continue}const plays=p.plays||{};let mine=null;if(plays.kind==='track'&&match.resolved.get(plays.ref))mine={kind:'track',trackId:match.resolved.get(plays.ref)};else if(plays.kind==='album'&&match.resolved.get(plays.ref))mine={kind:'album',albumId:match.resolved.get(plays.ref)};else if(plays.kind==='group'&&groupIds.has(plays.ref))mine={kind:'group',groupId:plays.ref};else if(plays.kind==='filter'&&plays.filter)mine={kind:'filter',filter:plays.filter};if(!mine){skipped+=1;continue}if(bodyOf(`preset:${p.id}`)&&keep)continue;const {category,plays:_plays,...rest}=p;writes.push({id:`preset:${p.id}`,kind:'preset',body:{...rest,id:p.id,categoryId:category,plays:mine}})}let values=0;for(const it of data.items||[]){const owner=match.resolved.get(it.ref);if(!owner)continue;const k=it.kind==='album'?'album':'track';for(const [fieldId,raw] of Object.entries(it.details||{})){const fk=fieldKinds.get(fieldId);const value=fk?normalize(fk,raw):null;if(value==null)continue;if(keep&&valueOf(k,owner,fieldId)!=null)continue;writes.push(detailWrite(k,owner,{id:fieldId},value));values+=1}}try{const result=await save(writes);$('ut-import-status').textContent=`Imported ${plural(values,'value','values')}${skipped?`; ${plural(skipped,'preset','presets')} left out because what ${skipped===1?'it plays':'they play'} isn’t here`:''}.${result.failed?` ${result.failed} couldn’t be saved; try again.`:''} Your phones take it at their next sync.`}catch(error){$('ut-import-status').textContent=error.message;$('ut-import-status').classList.add('error')}finally{button.disabled=false}}

// ---------------------------------------------------------------- dialog and page
function status(text,error=false){const s=$('ut-dialog-status');s.textContent=text;s.classList.toggle('error',error)}
function finish(result,text){if(result.failed)toast(`${text} ${result.failed} couldn’t be saved; try again.`);else toast(text)}
function dialog(title,draw,actions){const d=$('ut-dialog');$('ut-dialog-title').textContent=title;status('');draw();const bar=$('ut-dialog-actions');bar.innerHTML='';const cancel=document.createElement('button');cancel.type='button';cancel.className='ghost';cancel.textContent='Cancel';cancel.onclick=()=>d.close();bar.appendChild(cancel);for(const [label,style,run] of actions){const b=document.createElement('button');b.type='button';b.className=style;b.textContent=label;b.onclick=async()=>{b.disabled=true;try{const keep=await run();if(keep!==false)d.close()}catch(error){status(error.message,true)}finally{b.disabled=false}};bar.appendChild(b)}d.showModal()}
document.querySelectorAll('#ut-dialog [data-close]').forEach(b=>b.onclick=()=>$('ut-dialog').close());
function render(){document.querySelectorAll('#ut-tabs [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(!source){$('ut-body').innerHTML='<p class="ut-empty">Nothing from Undertone here yet. With a version of Lumae that has Undertone, turn on Sync with Lumae Analysis in Settings → Undertone, signed in to AudioMuse-AI as you are here.</p>';return}const info=sourceInfo();$('ut-title').textContent=info.libraryName||'Undertone';$('ut-summary').textContent=`${plural(items('track').length,'track','tracks')} · ${plural(items('album').length,'album','albums')} · ${plural(presets().length,'preset','presets')}${info.serverType?` · ${info.serverType==='jellyfin'?'Jellyfin':'Navidrome'}`:''}`;({music:renderMusic,presets:renderPresets,fields:renderFields,file:renderFile})[view]()}
document.querySelectorAll('#ut-tabs [data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
$('ut-source').onchange=async e=>{source=e.target.value;$('ut-body').innerHTML='<p class="ut-empty">Loading…</p>';await loadSource();render()};
(async()=>{try{const data=await req(`${api}/sources`);sources=data.sources||[];maxBatch=Math.max(1,Math.min(200,data.max_batch||200));const wanted=new URLSearchParams(location.search).get('source');source=(sources.find(s=>s.source===wanted)||sources[0])?.source||null;if(sources.length>1){$('ut-source-wrap').hidden=false;$('ut-source').innerHTML=sources.map(s=>`<option value="${esc(s.source)}" ${s.source===source?'selected':''}>${esc(s.library||'Undertone')} · ${plural(s.tracks,'track','tracks')}</option>`).join('')}if(source)await loadSource();render()}catch(error){$('ut-body').innerHTML=`<p class="ut-empty">${esc(error.message)}</p>`}})();
})();
</script>
"""
    return html.replace("__PRINCIPAL__", escape(principal_label)).replace(
        "__PRINCIPAL_DETAIL__", escape(principal_detail)
    )
